type:
∀ {α : Type} {lt : α → α → Prop} {decLt : DecidableRel lt} {irrefl : ∀ (x : α), ¬lt x x}
  {trans : ∀ {x y z : α}, lt x y → lt y z → lt x z} {lt_of_lt_of_not_gt : ∀ {x y z : α}, lt x y → ¬lt z y → lt x z}
  {lt_1 : α → α → Prop} {decLt_1 : DecidableRel lt_1} {irrefl_1 : ∀ (x : α), ¬lt_1 x x}
  {trans_1 : ∀ {x y z : α}, lt_1 x y → lt_1 y z → lt_1 x z}
  {lt_of_lt_of_not_gt_1 : ∀ {x y z : α}, lt_1 x y → ¬lt_1 z y → lt_1 x z},
  { lt := lt, decLt := decLt, irrefl := irrefl, trans := trans, lt_of_lt_of_not_gt := lt_of_lt_of_not_gt } =
      { lt := lt_1, decLt := decLt_1, irrefl := irrefl_1, trans := trans_1,
        lt_of_lt_of_not_gt := lt_of_lt_of_not_gt_1 } →
    lt = lt_1 ∧ HEq decLt decLt_1
